'use strict';
// L01-J baseline stroke dictionary <-> native editable-vector-path record. The expected values are the REAL serP(desP(dict))
// results of src/js/app.js at fbe4b8a3 over the shipped Paper.js (tests/native-object-vector-fixtures/stroke-oracle.json,
// generated by tools/gen-oracle.cjs); the record pins below are literal. Nothing here reimplements a baseline function.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const Stroke = require('../src/js/adapters/native-object-vector-stroke.js');
const Contract = require('../src/js/adapters/native-object-vector-contract.js');

const oracle = JSON.parse(fs.readFileSync(path.join(__dirname, 'native-object-vector-fixtures', 'stroke-oracle.json'), 'utf8'));
const NUMBERS = { '-0': -0, NaN: NaN, Infinity: Infinity, '-Infinity': -Infinity };
const dec = (v) => (Array.isArray(v) ? v.map(dec) : v && typeof v === 'object'
  ? ('$n' in v ? NUMBERS[v.$n] : Object.fromEntries(Object.entries(v).map(([k, x]) => [k, dec(x)]))) : v);
const cases = new Map(oracle.cases.map((c) => [c.id, { id: c.id, op: c.hasOp ? dec(c.op) : undefined, in: dec(c.in), out: dec(c.out), out2: dec(c.out2) }]));
const pick = (object, keys) => Object.fromEntries(keys.filter((key) => key in object).map((key) => [key, object[key]]));
const WHERE = { layerUid: 'L1', frame: 0 };
const map = (id, where) => { const c = cases.get(id); return Stroke.toRecord(c.in, where || WHERE, { opacity: c.op }); };
const B = (n) => n / 255;
const seg = (x, y, hix = 0, hiy = 0, hox = 0, hoy = 0) => ({ point: { x, y }, handleIn: { x: hix, y: hiy }, handleOut: { x: hox, y: hoy } });
const target = (strokeId = '', frame = 0) => ({ contextId: 'scene-root', frameScope: { kind: 'authored', frame }, layerUid: 'L1', strokeId });
const LINE = [seg(10, 20), seg(110, 70)];
const RECT = [seg(0, 0), seg(100, 0), seg(100, 50), seg(0, 50)];
const line = (vector, extra) => Object.assign({
  schemaVersion: 1, family: 'editable-vector-path', target: target(),
  geometry: { kind: 'cubic-path', closed: false, coordinateSpace: 'document-world', handleSpace: 'relative', segments: LINE },
  fill: null,
  vector: Object.assign({ stroke: { kind: 'solid', r: B(17), g: B(34), b: B(51), a: 1 }, hasRealStroke: true, strokeWidth: 4, strokeCap: 'round', strokeJoin: 'round', miterLimit: 10, dashOffset: 0, opacity: 1 }, vector),
}, extra);

test('the oracle is the pinned baseline run: 60 cases, the 81-member serP key list, every executed slice hashed', () => {
  assert.equal(oracle.commit, 'fbe4b8a33e6d5a229f014154df2ba21988a9fabc');
  assert.equal(oracle.generator, 'tools/gen-oracle.cjs');
  assert.equal(oracle.cases.length, 60);
  assert.equal(oracle.serpKeys.length, 81);
  assert.deepEqual(Object.keys(oracle.slices), ['colorHex8', 'applyBrushKeyline', '_r3', 'serP', 'desP']);
  for (const hash of [...Object.values(oracle.slices), oracle.pathFxSha256]) assert.match(hash, /^[0-9a-f]{64}$/);
  // Every member the record owns is a real serP member; pathFx and a pressure scalar are not.
  for (const key of Stroke.CARRIED) assert.ok(oracle.serpKeys.includes(key), key);
  assert.equal(oracle.serpKeys.includes('pathFx'), false);
  assert.equal(oracle.serpKeys.some((key) => /^pressure$/i.test(key)), false);
  assert.equal(new Set(oracle.cases.map((c) => c.id)).size, 60);
});

test('normalize reproduces serP(desP(dict)) for every record-relevant member of all 60 baseline cases', () => {
  for (const c of cases.values()) {
    const got = Stroke.normalize(c.in, c.op);
    assert.deepEqual(got, pick(c.out, Stroke.CARRIED), c.id);
    // and the stored output is a fixed point: the baseline serialises it to itself
    assert.deepEqual(Stroke.normalize(c.out, undefined), pick(c.out, Stroke.CARRIED), c.id + ' (stored form)');
    assert.deepEqual(pick(c.out2, Stroke.CARRIED), pick(c.out, Stroke.CARRIED), c.id + ' (baseline round trip)');
  }
});

test('literal records: open line, closed rect with alpha fill, white fallback, legacy white stroke', () => {
  assert.deepEqual(map('open-line').record, line());
  const rect = map('closed-rect').record;
  assert.deepEqual(rect, line({ stroke: { kind: 'solid', r: 1, g: 0, b: 0, a: 1 }, strokeWidth: 2 }, {
    geometry: { kind: 'cubic-path', closed: true, coordinateSpace: 'document-world', handleSpace: 'relative', segments: RECT },
    fill: { kind: 'solid', r: B(17), g: B(34), b: B(51), a: B(128) },
  }));
  // closure is independent of the anchors: the same four anchors, open or closed
  assert.equal(map('closed-key-absent').record.geometry.closed, false);
  assert.equal(map('closed-false-same-segments').record.geometry.closed, false);
  assert.deepEqual(map('closed-key-absent').record.geometry.segments, RECT);
  // hasRealStroke:false is authoritative: no stroke is inferred from the white fallback or from a real-looking colour
  for (const id of ['real-stroke-false-fallback-white', 'real-stroke-false-other-color']) {
    const record = map(id).record;
    assert.equal(record.vector.stroke, null, id);
    assert.equal(record.vector.hasRealStroke, false, id);
    assert.deepEqual(record.fill, { kind: 'solid', r: B(51), g: B(102), b: B(153), a: 1 }, id);
  }
  // legacy dictionaries without the flag restore the baseline #fff stroke, which then IS a real stroke
  for (const [id, color] of [['legacy-no-flag-no-color', 1], ['real-stroke-true-null-color', 1]]) {
    assert.deepEqual(map(id).record.vector.stroke, { kind: 'solid', r: color, g: color, b: color, a: 1 }, id);
    assert.equal(map(id).record.vector.hasRealStroke, true, id);
  }
  assert.deepEqual(map('legacy-no-flag-with-color').record.vector.stroke, { kind: 'solid', r: B(68), g: B(85), b: B(102), a: 1 });
});

test('literal records: stroke style, dash, paint order, opacity, the importer defaults', () => {
  assert.deepEqual(map('stroke-alpha-80').record.vector.stroke, { kind: 'solid', r: B(170), g: B(187), b: B(204), a: B(128) });
  assert.equal(map('stroke-alpha-00').record.vector.stroke.a, 0, 'a fully transparent stroke is still a real stroke');
  assert.equal(map('stroke-alpha-00').record.vector.hasRealStroke, true);
  assert.equal(map('width-zero-becomes-3').record.vector.strokeWidth, 3);
  assert.equal(map('width-absent-becomes-3').record.vector.strokeWidth, 3);
  assert.equal(map('width-fraction').record.vector.strokeWidth, 2.5);
  assert.deepEqual(pick(map('cap-butt-join-miter-limit-4').record.vector, ['strokeCap', 'strokeJoin', 'miterLimit']), { strokeCap: 'butt', strokeJoin: 'miter', miterLimit: 4 });
  assert.deepEqual(pick(map('cap-square-join-bevel-limit-absent').record.vector, ['strokeCap', 'strokeJoin', 'miterLimit']), { strokeCap: 'square', strokeJoin: 'bevel', miterLimit: 10 }, 'Paper default 10 when absent');
  assert.deepEqual(pick(map('cap-join-non-string').record.vector, ['strokeCap', 'strokeJoin']), { strokeCap: 'round', strokeJoin: 'round' });
  assert.equal(map('miter-limit-zero').record.vector.miterLimit, 0, 'an explicit zero stays zero');
  assert.equal('dashArray' in map('dash-empty-dropped').record.vector, false, 'an empty dash array is dropped, as the baseline drops it');
  assert.equal(map('dash-empty-dropped').record.vector.dashOffset, 0);
  assert.deepEqual(pick(map('dash-4-2-offset-0').record.vector, ['dashArray', 'dashOffset']), { dashArray: [4, 2], dashOffset: 0 });
  assert.deepEqual(pick(map('dash-3-offset-fraction').record.vector, ['dashArray', 'dashOffset']), { dashArray: [6, 3, 1], dashOffset: 1.5 });
  assert.equal(map('paint-order-stroke-first').record.vector.paintOrder, 'strokeFirst');
  assert.equal(map('paint-order-fill-first').record.vector.paintOrder, 'fillFirst');
  assert.equal('paintOrder' in map('paint-order-empty-string').record.vector, false);
  assert.equal(map('opacity-absent').record.vector.opacity, 1);
  assert.equal(map('opacity-zero').record.vector.opacity, 0, 'an explicit zero opacity stays zero');
  assert.equal(map('opacity-half').record.vector.opacity, 0.5);
  assert.equal(map('opacity-op-override').record.vector.opacity, 0.25, 'the third desP argument overrides');
  assert.equal(map('opacity-op-override-zero').record.vector.opacity, 0);
  assert.equal(map('fill-null').record.fill, null);
  assert.equal(map('fill-absent').record.fill, null);
  assert.equal(map('fill-empty-string').record.fill, null);
  assert.deepEqual(map('fill-short-hex').record.fill, { kind: 'solid', r: B(170), g: B(187), b: B(204), a: 1 });
  assert.deepEqual(map('fill-alpha-40').record.fill, { kind: 'solid', r: B(16), g: B(32), b: B(48), a: B(64) });
});

test('literal records: outline coordinates are rounded to 3 decimals, -0 survives, non-finite becomes 0', () => {
  const r = map('round-3-decimals').record.geometry.segments;
  assert.deepEqual(r[0], seg(1.235, -1.235, 0, -0, 2.001, 1.001));
  assert.ok(Object.is(r[0].handleIn.y, -0), '-0 is preserved (JSON transport drops the sign; the record keeps what the baseline kept)');
  assert.deepEqual(r[1], seg(-0, 0.001, 0, 123456.79, -2.5, 100));
  assert.ok(Object.is(r[1].point.x, -0));
  assert.deepEqual(map('nonfinite-coords').record.geometry.segments, [seg(0, 0, 0, 1, 2, 0), seg(3, 4)]);
  assert.equal(Stroke.r3(0.0005), 0.001);
  assert.equal(Stroke.r3(-0.0005), -0);
  assert.equal(Stroke.r3(Infinity), 0);
  assert.equal(Stroke.r3(NaN), 0);
});

test('literal records: a pressure ribbon has no real stroke and carries the centreline and profile by value', () => {
  const ribbon = map('vb-basic').record;
  assert.equal(ribbon.vector.stroke, null);
  assert.equal(ribbon.vector.hasRealStroke, false, 'the baseline forces hasRealStroke:false for a ribbon whatever the input says');
  assert.deepEqual(ribbon.fill, { kind: 'solid', r: 0, g: 0, b: 0, a: 1 });
  assert.equal(ribbon.geometry.closed, true);
  assert.deepEqual(ribbon.geometry.segments[1], seg(60.123, 5.5, -2.5, 0, 3.75, 0), 'outline rounded');
  assert.deepEqual(ribbon.vectorExt, {
    pressure: {
      centerSegments: [
        { point: { x: 1.23456789, y: 2.34567891 }, handleIn: { x: 0, y: 0 }, handleOut: { x: 3.1111111, y: 0.2222222 }, width: 6.5 },
        { point: { x: 50.987654321, y: 40.123456789 }, handleIn: { x: -3.1111111, y: 0.2222222 }, handleOut: { x: 4.4444444, y: -1.5555555 }, width: 9.25 },
        { point: { x: 120.5, y: 41.75 }, handleIn: { x: -4.4444444, y: 1.5555555 }, handleOut: { x: 0, y: 0 }, width: 2 },
      ],
      widthProfile: [{ t: 0, width: 2 }, { t: 0.25, width: 4.82842712474619 }, { t: 0.5, width: 6 }, { t: 0.75, width: 4.82842712474619 }, { t: 1, width: 2.0000000000000004 }],
      strokeProfile: 'taper-both', profileBase: 12,
    },
  }, 'centreline and profile are NOT rounded');
  for (const id of ['vb-has-real-stroke-true', 'vb-fill-shape', 'vb-stroke-color-absent']) {
    assert.equal(map(id).record.vector.stroke, null, id);
    assert.equal(map(id).record.vector.hasRealStroke, false, id);
  }
  assert.deepEqual(map('vb-no-center-no-profile').record.vectorExt, { pressure: {} }, 'a ribbon without centreline or profile is still a vector brush');
  assert.deepEqual(map('vb-empty-arrays-zero-base').record.vectorExt, { pressure: { centerSegments: [], widthProfile: [] } }, 'empty arrays are kept; strokeProfile "" and profileBase 0 are dropped');
  assert.deepEqual(map('vb-fill-shape').unmapped, ['isFillShape'], 'the fill-shape flag has no record slot and is reported');
  // pressure-looking members on a plain stroke are dropped by the baseline and are not a ribbon
  const plain = map('non-vb-with-pressure-fields');
  assert.equal('vectorExt' in plain.record, false);
  assert.deepEqual(plain.unmapped, ['isFillShape'], 'the baseline drops the ribbon members of a plain stroke; the mapper mirrors desP');
});

test('literal records: paramShape and boxAngle travel by value, a null or absent paramShape stays absent', () => {
  const rect = map('param-rect-with-box-angle').record;
  assert.deepEqual(rect.vectorExt, { paramShape: { kind: 'rect', tl: 5, tr: 0, br: 0, bl: 10, box: { x1: 0, y1: 0, x2: 100, y2: 50 } }, boxAngle: 30 });
  assert.deepEqual(map('param-star').record.vectorExt, { paramShape: { kind: 'star', pointCount: 5, innerRatio: 0.5, cornerRadius: 0, box: { x1: 0, y1: 0, x2: 100, y2: 50 } } });
  assert.equal(map('param-ellipse').record.vectorExt.paramShape.kind, 'ellipse');
  assert.equal('vectorExt' in map('param-null').record, false);
  assert.equal('vectorExt' in map('param-absent').record, false);
  // an unknown member of a kind is a typed refusal, not a dropped one
  const stray = Stroke.toRecord(Object.assign({}, cases.get('param-star').in, { paramShape: { kind: 'star', pointCount: 5, tl: 1 } }), WHERE);
  assert.equal(stray.ok, false); assert.equal(stray.code, 'unsupported_member'); assert.deepEqual(stray.members, ['paramShape.tl']);
  assert.equal(Stroke.toRecord(Object.assign({}, cases.get('param-star').in, { paramShape: { kind: 'blob' } }), WHERE).code, 'unsupported_member');
});

test('every baseline case maps, or is refused with a named reason; mapped records are valid and invert to the baseline dictionary', () => {
  const refused = [];
  for (const c of cases.values()) {
    const mapped = Stroke.toRecord(c.in, WHERE, { opacity: c.op });
    if (!mapped.ok) { refused.push([c.id, mapped.code]); continue; }
    assert.doesNotThrow(() => Contract.record(mapped.record, mapped.record.target.strokeId === ''), c.id);
    assert.deepEqual(Stroke.toDict(mapped.record), pick(c.out, Stroke.CARRIED), c.id + ' inverse');
    assert.deepEqual(Stroke.toRecord(c.out, WHERE).record, mapped.record, c.id + ' the stored form maps to the same record');
  }
  assert.deepEqual(refused, [
    ['segments-empty', 'unsupported_geometry'], ['single-anchor-open', 'unsupported_geometry'], ['single-anchor-closed', 'unsupported_geometry'],
    ['bitmap-pressure-profile-carried', 'unavailable'], ['path-fx-key-on-stroke-dict-dropped', 'unavailable'],
  ]);
  assert.equal(refused.length + 55, 60);
});

test('colours: #rgb, #rrggbb and #rrggbbaa in; opaque #rrggbb or #rrggbbaa out; every other form is a typed refusal', () => {
  const table = [['#000', [0, 0, 0, 1], '#000000'], ['#abc', [B(170), B(187), B(204), 1], '#aabbcc'], ['#FF8000', [1, B(128), 0, 1], '#ff8000'], ['#aabbcc80', [B(170), B(187), B(204), B(128)], '#aabbcc80'],
    ['#11223300', [B(17), B(34), B(51), 0], '#11223300'], ['#112233ff', [B(17), B(34), B(51), 1], '#112233']];
  for (const [text, [r, g, b, a], back] of table) {
    assert.deepEqual(Stroke.parseColor(text), { kind: 'solid', r, g, b, a }, text);
    assert.equal(Stroke.colorHex8(Stroke.parseColor(text)), back, text);
  }
  for (let byte = 0; byte < 256; byte += 1) {
    const h = byte.toString(16).padStart(2, '0');
    assert.equal(Stroke.colorHex8({ r: B(byte), g: B(255 - byte), b: B(byte), a: 1 }), `#${h}${(255 - byte).toString(16).padStart(2, '0')}${h}`);
    if (byte < 255) assert.equal(Stroke.colorHex8({ r: 0, g: 0, b: 0, a: B(byte) }), `#000000${h}`);
  }
  const base = cases.get('open-line').in;
  for (const bad of ['red', 'rgb(1,2,3)', '#12', '#1234', '#12345', '#1234567', '#gggggg', 5, {}]) {
    const result = Stroke.toRecord(Object.assign({}, base, { strokeColor: bad }), WHERE);
    assert.equal(result.ok, false, String(bad)); assert.equal(result.code, 'unsupported_color', String(bad));
    assert.equal(Stroke.toRecord(Object.assign({}, base, { fillColor: bad }), WHERE).ok, false, 'fill ' + String(bad));
  }
});

test('members the record cannot carry without changing the look refuse; the rest are reported, never silently dropped', () => {
  const base = cases.get('open-line').in;
  for (const key of Stroke.REFUSED) {
    const result = Stroke.toRecord(Object.assign({}, base, { [key]: key === 'effects' ? [{ type: 'blur' }] : { x: 1 } }), WHERE);
    assert.equal(result.ok, false, key); assert.equal(result.code, 'unavailable', key); assert.deepEqual(result.members, [key], key);
  }
  assert.equal(Stroke.toRecord(Object.assign({}, base, { effects: [], fillGradient: null, isMask: false }), WHERE).ok, true, 'empty, null and false members are the baseline absent');
  const kept = Stroke.toRecord(Object.assign({}, base, { fillSeed: [1, 2], fillGapPx: 0, groupId: 'g_9', tweenOn: true, ownerId: 'u1', xformAnchorKey: 'tl' }), WHERE);
  assert.equal(kept.ok, true);
  assert.deepEqual(kept.record.vectorExt.fillTrace, { seed: [1, 2], gapPx: 0 }, 'zero is persisted as a value');
  assert.deepEqual(Stroke.toDict(kept.record).fillSeed, [1, 2]);
  assert.equal(Stroke.toDict(kept.record).fillGapPx, 0);
  assert.deepEqual(kept.unmapped, ['groupId', 'tweenOn', 'ownerId', 'xformAnchorKey'], 'only fields without native storage stay explicitly unmapped');
  assert.equal(Stroke.toRecord(cases.get('stroke-id-kept').in, WHERE).authoredStrokeId, 'st_01');
  assert.deepEqual(Stroke.toRecord(cases.get('stroke-id-kept').in, WHERE).unmapped, ['groupId']);
  assert.equal(Stroke.toRecord(base, WHERE).authoredStrokeId, null);
});

test('the target decides the identity: a create is blank, an import keeps the authored id, a scope and a frame are carried', () => {
  const dict = cases.get('stroke-id-kept').in;
  assert.equal(Stroke.toRecord(dict, WHERE).record.target.strokeId, 'st_01', 'the authored id is kept by default');
  assert.equal(Stroke.toRecord(dict, { layerUid: 'L1', frame: 4, strokeId: '' }).record.target.strokeId, '', 'a create blanks it');
  assert.equal(Stroke.toRecord(dict, { layerUid: 'L1', frame: 4, strokeId: 'native-stroke:9:0' }).record.target.strokeId, 'native-stroke:9:0');
  assert.deepEqual(Stroke.toRecord(dict, { layerUid: 'L9', frame: 12, scope: 'reference' }).record.target, { contextId: 'scene-root', frameScope: { kind: 'reference', frame: 12 }, layerUid: 'L9', strokeId: 'st_01' });
  assert.equal(Stroke.toRecord(cases.get('open-line').in, WHERE).record.target.strokeId, '', 'no authored id: blank');
  for (const bad of [null, {}, { layerUid: '', frame: 0 }, { layerUid: 'L1', frame: -1 }, { layerUid: 'L1', frame: 1.5 }, { layerUid: 'L1' }]) {
    const result = Stroke.toRecord(cases.get('open-line').in, bad);
    assert.equal(result.ok, false); assert.equal(result.code, 'invalid_target');
  }
  for (const bad of [null, [], { segments: 'x' }, { segments: [null] }, { segments: [{ point: [1], handleIn: [0, 0], handleOut: [0, 0] }] }]) {
    assert.equal(Stroke.toRecord(bad, WHERE).ok, false);
  }
  assert.equal(Stroke.toRecord(Object.assign({}, cases.get('open-line').in, { miterLimit: 'x' }), WHERE).code, 'invalid_dict');
});

test('toDict inverts a record on its own and never invents a pressure scalar, a pathFx member or a stroke colour', () => {
  const dict = Stroke.toDict(map('vb-basic').record);
  assert.equal(dict.strokeColor, null); assert.equal(dict.hasRealStroke, false); assert.equal(dict.isVectorBrush, true);
  assert.equal('pathFx' in dict, false); assert.equal('pressure' in dict, false);
  const fallback = Stroke.toDict(map('real-stroke-false-other-color').record);
  assert.equal(fallback.strokeColor, '#ffffff', 'serP writes the white fallback beside hasRealStroke:false');
  assert.equal(fallback.hasRealStroke, false);
  const bare = line({}); delete bare.vector.miterLimit; delete bare.vector.dashOffset;
  assert.equal('miterLimit' in Stroke.toDict(bare), false, 'an absent miter limit stays absent');
  assert.equal('dashOffset' in Stroke.toDict(bare), false);
  assert.equal(Stroke.toDict({ family: 'closed-solid-fill-cubic-path' }).ok, false);
});

test('the layer path-effect stack: the baseline defaults, hasAny and the typed refusal of what the owner cannot store', () => {
  assert.deepEqual(Stroke.FX_TYPES, oracle.pathFx.types.map((t) => t.id));
  for (const type of ['zigzag', 'roughen']) assert.deepEqual(Stroke.defaultsFor(type), dec(oracle.pathFx.defaults[type]), type);
  assert.deepEqual(Stroke.defaultsFor('zigzag'), { type: 'zigzag', enabled: true, p1: 12, p2: 4, p3: 0 });
  assert.deepEqual(Stroke.defaultsFor('roughen'), { type: 'roughen', enabled: true, p1: 8, p2: 6, p3: 0 });
  assert.deepEqual(Stroke.defaultsFor('wave'), dec(oracle.pathFx.defaults.unknown));
  const stacks = dec(oracle.pathFx.stacks);
  for (const [name, expected] of Object.entries(oracle.pathFx.hasAny)) assert.equal(Stroke.hasActive(stacks[name]), expected, name);
  assert.deepEqual(Stroke.stackToNative(stacks.zigzagDefault), { ok: true, stack: [{ type: 'zigzag', enabled: true, p1: 12, p2: 4, p3: 0 }] });
  assert.deepEqual(Stroke.stackToNative(stacks.empty), { ok: true, stack: [] }, 'an authored empty stack is a value');
  const kept = Stroke.stackToNative([{ type: 'roughen', enabled: false, p1: 3 }, { type: 'zigzag', p1: null }, { type: 'zigzag', enabled: true, extra: 1 }]);
  assert.deepEqual(kept.stack, [{ type: 'roughen', enabled: false, p1: 3 }, { type: 'zigzag', p1: null }, { type: 'zigzag', enabled: true }], 'absent stays absent, null stays null, order is evaluation order');
  const bad = Stroke.stackToNative(stacks.mixed);
  assert.equal(bad.ok, false); assert.equal(bad.code, 'unsupported_effect'); assert.equal(bad.index, 2, 'the baseline would skip the unknown type silently; the owner cannot store it');
  assert.equal(Stroke.stackToNative(stacks.unknownOnly).ok, false);
  for (const value of [undefined, null, {}, 'zigzag']) assert.equal(Stroke.stackToNative(value).ok, false);
  assert.doesNotThrow(() => Contract.payload(Contract.EFFECTS, { command: 'object.path.effects.set', layerUid: 'L1', stack: kept.stack }));
});

test('negative controls: the oracle discriminates the rules a careless mapper would get wrong', () => {
  const all = [...cases.values()];
  // 1. inferring a stroke from strokeColor (the white fallback) instead of hasRealStroke
  const fallback = all.filter((c) => c.out.hasRealStroke === false && c.out.strokeColor !== null);
  assert.deepEqual(fallback.map((c) => c.id), ['real-stroke-false-fallback-white', 'real-stroke-false-other-color']);
  for (const c of fallback) assert.notEqual(Stroke.parseColor(c.out.strokeColor), null);   // a naive mapper would build a stroke here
  // 2. no strokeWidth || 3
  assert.deepEqual(all.filter((c) => !c.in.strokeWidth).map((c) => c.id), ['width-zero-becomes-3', 'width-absent-becomes-3']);
  // 3. dropping alpha (six-digit colours only)
  assert.equal(all.filter((c) => /^#[0-9a-f]{8}$/.test(c.out.fillColor || '') || /^#[0-9a-f]{8}$/.test(c.out.strokeColor || '')).length, 6);
  // 4. no outline rounding; 5. a ribbon keeping a stroke
  assert.equal(all.filter((c) => JSON.stringify(c.in.segments) !== JSON.stringify(c.out.segments)).length, 10);
  assert.equal(all.filter((c) => c.out.isVectorBrush).length, 6);
  // and the mapper under test sees each of them
  assert.equal(map('real-stroke-false-other-color').record.vector.hasRealStroke, false);
  assert.equal(map('width-zero-becomes-3').record.vector.strokeWidth, 3);
  assert.notEqual(map('stroke-alpha-80').record.vector.stroke.a, 1);
  assert.notDeepEqual(map('round-3-decimals').record.geometry.segments[0].point, { x: cases.get('round-3-decimals').in.segments[0].point[0], y: cases.get('round-3-decimals').in.segments[0].point[1] });
  // a tampered expectation fails the comparison the first tests use
  const tampered = pick(cases.get('stroke-alpha-80').out, Stroke.CARRIED); tampered.strokeColor = '#aabbcc';
  assert.notDeepEqual(Stroke.normalize(cases.get('stroke-alpha-80').in), tampered);
  const wrongFlag = pick(cases.get('real-stroke-false-other-color').out, Stroke.CARRIED); wrongFlag.hasRealStroke = true;
  assert.notDeepEqual(Stroke.normalize(cases.get('real-stroke-false-other-color').in), wrongFlag);
});


test('stored baseline two-stop gradients travel through the real mapper and inverse without normalization', () => {
  const base=JSON.parse(JSON.stringify(cases.values().next().value.in));
  for (const kind of ['linear','radial']) {
    const gradient={kind,from:[1.25,-2],to:[31.25,12],stops:[{offset:1,color:'#11223380'},{offset:0,color:'#AAbbCC'}]};
    const dict=Object.assign({},base,{fillGradient:gradient,hasRealStroke:false,fillColor:'#ff0000'});
    const before=JSON.stringify(dict), mapped=Stroke.toRecord(dict,WHERE);
    assert.equal(mapped.ok,true); assert.deepEqual(mapped.unmapped,[]);
    assert.deepEqual(mapped.record.vectorExt.fillGradient,gradient);
    assert.doesNotThrow(()=>Contract.record(mapped.record,true));
    assert.deepEqual(Stroke.toDict(mapped.record).fillGradient,gradient);
    assert.equal(JSON.stringify(dict),before);
    gradient.from[0]=999; assert.equal(mapped.record.vectorExt.fillGradient.from[0],1.25,'no mutable source alias');
  }
});

test('stored gradient mapping refuses unsupported stop counts, malformed fields and pressure without dropping paint', () => {
  const base=JSON.parse(JSON.stringify(cases.values().next().value.in));
  const good={kind:'linear',from:[0,0],to:[10,0],stops:[{offset:0,color:'#ff0000'},{offset:1,color:'#0000ff'}]};
  for (const change of [g=>{g.stops.pop();},g=>{g.stops.push({offset:0.5,color:'#00ff00'});},g=>{g.kind='conic';},
    g=>{g.from=[0,Infinity];},g=>{g.stops[0].color='url(secret)';},g=>{g.extra=true;}]) {
    const gradient=JSON.parse(JSON.stringify(good));change(gradient);
    assert.equal(Stroke.toRecord(Object.assign({},base,{fillGradient:gradient}),WHERE).ok,false);
  }
  assert.equal(Stroke.toRecord(Object.assign({},base,{fillGradient:good,isVectorBrush:true}),WHERE).ok,false);
});

test('linked fill mapper retains separate authored geometry and absent/false/true roles on the actual conversion path', () => {
  const base = { segments: [{ point: [0,0], handleIn: [0,0], handleOut: [0,0] }, { point: [20,5], handleIn: [0,0], handleOut: [0,0] }],
    closed: true, fillColor: '#ff0000', strokeColor: null, hasRealStroke: false, strokeWidth: 6, strokeCap: 'round', strokeJoin: 'round', opacity: 1 };
  const primary = { ...base, isVectorBrush: true, linkedFillId: 'linked-original', isLinkedFillCompanion: false,
    centerSegments: [{ point:[0,1], handleIn:[0,0], handleOut:[0,0], width:0.5 }, { point:[20,1], handleIn:[0,0], handleOut:[0,0], width:3 }] };
  const companion = { ...base, linkedFillId: 'linked-original', isLinkedFillCompanion: true,
    segments: [{ point:[-10,-10], handleIn:[0,0], handleOut:[0,0] }, { point:[40,20], handleIn:[0,0], handleOut:[0,0] }] };
  const a=Stroke.toRecord(primary,{...WHERE,strokeId:'primary'}), b=Stroke.toRecord(companion,{...WHERE,strokeId:'companion'});
  assert.equal(a.ok,true);assert.equal(b.ok,true);
  assert.notDeepEqual(a.record.geometry,b.record.geometry,'the backdrop is never substituted with the ribbon contour');
  assert.equal(a.record.vectorExt.isLinkedFillCompanion,false);assert.equal(b.record.vectorExt.isLinkedFillCompanion,true);
  assert.equal(a.record.vectorExt.linkedFillId,b.record.vectorExt.linkedFillId);
  for (const result of [a,b]) {
    Contract.record(result.record);
    const dict=Stroke.toDict(result.record);
    assert.equal(dict.linkedFillId,'linked-original');
    assert.equal(dict.isLinkedFillCompanion,result.record.vectorExt.isLinkedFillCompanion);
    assert.deepEqual(Stroke.toRecord(dict,{...WHERE,strokeId:result.record.target.strokeId}).record,result.record);
    assert.equal(result.unmapped.includes('linkedFillId'),false);
  }
  const noFlag={...primary};delete noFlag.isLinkedFillCompanion;
  const absent=Stroke.toRecord(noFlag,WHERE);
  assert.equal(absent.ok,true);assert.equal(Object.hasOwn(absent.record.vectorExt,'isLinkedFillCompanion'),false);
  assert.equal(Object.hasOwn(Stroke.toDict(absent.record),'isLinkedFillCompanion'),false);
  const falseOnly=Stroke.toRecord({...base,isLinkedFillCompanion:false},WHERE);
  assert.equal(falseOnly.ok,true);assert.equal(Stroke.toDict(falseOnly.record).isLinkedFillCompanion,false);
  Contract.record(absent.record,true);Contract.record(falseOnly.record,true);
  for (const mutate of [r=>r.vectorExt.linkedFillId=null,r=>r.vectorExt.linkedFillId='x'.repeat(129),
    r=>r.vectorExt.linkedFillId='bad\u0000id',r=>r.vectorExt.isLinkedFillCompanion=null,
    r=>delete r.vectorExt.linkedFillId,r=>r.fill=null,r=>r.target.frameScope.kind='evaluated']) {
    const bad=JSON.parse(JSON.stringify(b.record));mutate(bad);assert.throws(()=>Contract.record(bad));
  }
  for (const bad of [{...primary,linkedFillId:null},{...primary,isLinkedFillCompanion:null},
    {...primary,centerSegments:[]},{...base,linkedFillId:'linked-original'},
    {...companion,linkedFillId:''},{...companion,isVectorBrush:true,centerSegments:primary.centerSegments},
    {...companion,fillColor:null},{...primary,linkedFillId:'x'.repeat(129)}]) assert.equal(Stroke.toRecord(bad,WHERE).ok,false);
});
